-- Name: wager_transactions; Type: TABLE; Schema: public; Owner: -

CREATE TABLE public.wager_transactions (
    id uuid NOT NULL,
    provider_id text NOT NULL,
    external_transaction_id text NOT NULL,
    idempotency_key text NOT NULL,
    payload_hash character(64) NOT NULL,
    wallet_id uuid NOT NULL,
    player_id text NOT NULL,
    round_id text NOT NULL,
    game_id text NOT NULL,
    kind text NOT NULL,
    amount numeric(20,2) NOT NULL,
    currency character(3) NOT NULL,
    reference_external_transaction_id text,
    reference_transaction_id uuid,
    status text NOT NULL,
    failure_code text,
    result_balance numeric(20,2),
    reference_attempts integer DEFAULT 0 NOT NULL,
    next_reference_check_at timestamp with time zone,
    processed_at timestamp with time zone,
    created_at timestamp with time zone NOT NULL,
    updated_at timestamp with time zone NOT NULL,
    result_currency character(3),
    CONSTRAINT wager_transactions_amount_check CHECK ((amount >= (0)::numeric)),
    CONSTRAINT wager_transactions_currency_check CHECK ((currency ~ '^[A-Z]{3}$'::text)),
    CONSTRAINT wager_transactions_external_transaction_id_check CHECK (((length(external_transaction_id) >= 1) AND (length(external_transaction_id) <= 256))),
    CONSTRAINT wager_transactions_idempotency_key_check CHECK (((length(idempotency_key) >= 1) AND (length(idempotency_key) <= 512))),
    CONSTRAINT wager_transactions_kind_check CHECK ((kind = ANY (ARRAY['OPENING'::text, 'BET'::text, 'WIN'::text, 'LOSS'::text, 'REFUND'::text, 'ROLLBACK'::text]))),
    CONSTRAINT wager_transactions_provider_id_check CHECK (((length(provider_id) >= 1) AND (length(provider_id) <= 128))),
    CONSTRAINT wager_transactions_reference_attempts_check CHECK ((reference_attempts >= 0)),
    CONSTRAINT wager_transactions_result_balance_check CHECK ((result_balance >= (0)::numeric)),
    CONSTRAINT wager_transactions_status_check CHECK ((status = ANY (ARRAY['PENDING'::text, 'PENDING_REFERENCE'::text, 'PROCESSED'::text, 'REJECTED'::text, 'FAILED'::text]))),
    CONSTRAINT wager_tx_amount_positive_unless_loss CHECK (((kind = 'LOSS'::text) OR (amount > (0)::numeric))),
    CONSTRAINT wager_tx_failure_code_iff_failed CHECK (((status = ANY (ARRAY['REJECTED'::text, 'FAILED'::text])) = (failure_code IS NOT NULL))),
    CONSTRAINT wager_tx_pending_reference_has_next_check CHECK (((status <> 'PENDING_REFERENCE'::text) OR (next_reference_check_at IS NOT NULL))),
    CONSTRAINT wager_tx_result_currency_with_balance CHECK (((result_balance IS NULL) = (result_currency IS NULL))),
    CONSTRAINT wager_tx_reversal_requires_reference CHECK (((kind <> ALL (ARRAY['REFUND'::text, 'ROLLBACK'::text])) OR (reference_external_transaction_id IS NOT NULL))),
    CONSTRAINT wager_tx_terminal_has_processed_at CHECK (((status <> ALL (ARRAY['PROCESSED'::text, 'REJECTED'::text, 'FAILED'::text])) OR (processed_at IS NOT NULL)))
);

-- Name: wallet_ledger_entries; Type: TABLE; Schema: public; Owner: -

CREATE TABLE public.wallet_ledger_entries (
    sequence bigint NOT NULL,
    id uuid NOT NULL,
    wallet_id uuid NOT NULL,
    transaction_id uuid NOT NULL,
    direction text NOT NULL,
    amount numeric(20,2) NOT NULL,
    currency character(3) NOT NULL,
    balance_before numeric(20,2) NOT NULL,
    balance_after numeric(20,2) NOT NULL,
    created_at timestamp with time zone NOT NULL,
    CONSTRAINT ledger_entry_balanced CHECK ((((direction = 'CREDIT'::text) AND (balance_after = (balance_before + amount))) OR ((direction = 'DEBIT'::text) AND (balance_after = (balance_before - amount))))),
    CONSTRAINT wallet_ledger_entries_amount_check CHECK ((amount > (0)::numeric)),
    CONSTRAINT wallet_ledger_entries_balance_after_check CHECK ((balance_after >= (0)::numeric)),
    CONSTRAINT wallet_ledger_entries_balance_before_check CHECK ((balance_before >= (0)::numeric)),
    CONSTRAINT wallet_ledger_entries_direction_check CHECK ((direction = ANY (ARRAY['DEBIT'::text, 'CREDIT'::text])))
);

